css:
.mdt-float-dock{
  --mdt-fd-ink:#E9EDF8;
  --mdt-fd-dim:#79839E;
  --mdt-fd-accent:#7C9BFF;
  box-sizing:border-box;width:100%;max-width:340px;margin:0 auto;
  font:600 11px/1.2 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mdt-fd-ink);-webkit-font-smoothing:antialiased;
}
.mdt-float-dock *{box-sizing:border-box}
.mdt-float-dock svg{width:15px;height:15px;display:block;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round}
.mdt-float-dock-stage{position:relative;padding:52px 10px 20px;border-radius:16px;overflow:hidden;border:1px solid rgba(255,255,255,.07);background:radial-gradient(130% 92% at 50% 4%,#171C29,#0B0D14 74%)}
.mdt-float-dock-grid{position:absolute;inset:0;background-image:linear-gradient(rgba(255,255,255,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.05) 1px,transparent 1px);background-size:24px 24px;-webkit-mask-image:radial-gradient(78% 68% at 50% 34%,#000,transparent);mask-image:radial-gradient(78% 68% at 50% 34%,#000,transparent)}
.mdt-float-dock-art{position:absolute;inset:0;pointer-events:none}
.mdt-float-dock-art i{position:absolute;display:block;border-radius:6px;border:1px dashed rgba(255,255,255,.13)}
.mdt-float-dock-art i:nth-child(1){left:16px;top:14px;width:74px;height:26px;background:rgba(255,255,255,.03)}
.mdt-float-dock-art i:nth-child(2){right:18px;top:10px;width:46px;height:46px;border-radius:50%;background:rgba(124,155,255,.10);border-color:rgba(124,155,255,.42)}
.mdt-float-dock-art i:nth-child(3){left:34%;top:20px;width:58px;height:16px;background:rgba(255,255,255,.03)}
.mdt-float-dock-bar{position:relative;z-index:1;isolation:isolate;display:flex;align-items:center;gap:2px;width:-webkit-max-content;width:max-content;max-width:100%;margin:0 auto;padding:5px;border-radius:999px;border:1px solid rgba(255,255,255,.11);background:linear-gradient(180deg,rgba(33,39,56,.94),rgba(13,16,25,.94));box-shadow:0 20px 36px -18px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,255,255,.09);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px)}
.mdt-float-dock-bar::before{content:"";position:absolute;z-index:-1;inset:-12px -8px -16px;border-radius:999px;background:radial-gradient(58% 120% at 50% 55%,rgba(124,155,255,.30),transparent 72%);filter:blur(9px)}
.mdt-float-dock-sep{width:1px;height:18px;margin:0 4px;background:rgba(255,255,255,.13)}
.mdt-float-dock-btn{position:relative;display:grid;place-items:center;width:32px;height:32px;padding:0;border:0;border-radius:11px;background:transparent;color:var(--mdt-fd-dim);cursor:pointer;transition:color .18s ease,background .18s ease,transform .24s cubic-bezier(.2,.9,.3,1.25),box-shadow .18s ease}
.mdt-float-dock-btn:hover{color:var(--mdt-fd-ink);background:rgba(255,255,255,.08);transform:translateY(-3px)}
.mdt-float-dock-btn:active{transform:translateY(0) scale(.93)}
.mdt-float-dock-btn:focus-visible{outline:2px solid var(--mdt-fd-accent);outline-offset:2px;color:var(--mdt-fd-ink)}
.mdt-float-dock-btn[aria-pressed="true"]{color:#0A0C12;background:linear-gradient(180deg,#A9BCFF,#6C8BF6);box-shadow:0 8px 16px -8px rgba(108,139,246,.95)}
.mdt-float-dock-cta{color:#7BE8C0}
.mdt-float-dock-cta:hover{color:#8FF6D0;background:rgba(123,232,192,.12)}
.mdt-float-dock-dot{position:absolute;top:2px;right:1px;min-width:14px;height:14px;padding:0 3px;border-radius:999px;font-size:9px;line-height:14px;font-weight:700;color:#0A0C12;background:#FFB454;border:2px solid #12161F}
.mdt-float-dock-btn::after{content:attr(data-tip);position:absolute;left:50%;bottom:calc(100% + 13px);transform:translate(-50%,5px);padding:4px 8px;border-radius:8px;white-space:nowrap;font-size:10px;font-weight:600;letter-spacing:.02em;color:#DCE3F5;background:#1B2132;border:1px solid rgba(255,255,255,.11);box-shadow:0 10px 20px -12px #000;opacity:0;pointer-events:none;transition:opacity .16s ease,transform .16s ease}
.mdt-float-dock-btn:hover::after,.mdt-float-dock-btn:focus-visible::after{opacity:1;transform:translate(-50%,0)}
@media (prefers-reduced-motion: reduce){
  .mdt-float-dock-btn{transition:color .01s linear,background .01s linear}
  .mdt-float-dock-btn:hover{transform:none}
  .mdt-float-dock-btn:active{transform:none}
  .mdt-float-dock-btn::after{transition:none;transform:translate(-50%,0)}
}

js:
var bar = root.querySelector('.mdt-float-dock-bar');
var all = Array.prototype.slice.call(root.querySelectorAll('.mdt-float-dock-btn'));
var tools = all.filter(function(b){ return b.hasAttribute('data-tool'); });
all.forEach(function(b, i){ b.tabIndex = i === 0 ? 0 : -1; });

function focusAt(i){
  i = (i + all.length) % all.length;
  all.forEach(function(b){ b.tabIndex = -1; });
  all[i].tabIndex = 0;
  all[i].focus();
}
bar.addEventListener('keydown', function(e){
  var i = all.indexOf(e.target);
  if (i < 0) return;
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown'){ e.preventDefault(); focusAt(i + 1); }
  else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp'){ e.preventDefault(); focusAt(i - 1); }
  else if (e.key === 'Home'){ e.preventDefault(); focusAt(0); }
  else if (e.key === 'End'){ e.preventDefault(); focusAt(all.length - 1); }
});
tools.forEach(function(b){
  b.addEventListener('click', function(){
    tools.forEach(function(o){ o.setAttribute('aria-pressed', o === b ? 'true' : 'false'); });
  });
});
var note = root.querySelector('.mdt-float-dock-note');
note.addEventListener('click', function(){
  note.setAttribute('aria-pressed', note.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
});

css:
.mdt-selection-bubble{
  --mdt-sb-ink:#D8DEEE;
  --mdt-sb-accent:#8F7BFF;
  position:relative;box-sizing:border-box;width:100%;max-width:340px;margin:0 auto;padding:54px 14px 13px;
  border-radius:14px;border:1px solid rgba(255,255,255,.07);background:linear-gradient(180deg,#101320,#0A0C13);
  font:400 12.5px/1.62 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mdt-sb-ink);-webkit-font-smoothing:antialiased;
}
.mdt-selection-bubble *{box-sizing:border-box}
.mdt-selection-bubble svg{width:14px;height:14px;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.mdt-selection-bubble-copy{margin:0;-webkit-user-select:text;user-select:text;cursor:text}
.mdt-selection-bubble-copy::selection{background:rgba(143,123,255,.42);color:#fff}
.mdt-selection-bubble-hint{margin:10px 0 0;font-size:10.5px;letter-spacing:.03em;color:#5D6683}
.mdt-selection-bubble-sel{border-radius:4px;padding:1px 2px;background:rgba(143,123,255,.26);box-shadow:inset 0 0 0 1px rgba(143,123,255,.38);color:#F0EEFF}
.mdt-selection-bubble-sel.is-b{font-weight:700}
.mdt-selection-bubble-sel.is-i{font-style:italic}
.mdt-selection-bubble-sel.is-s{text-decoration:line-through}
.mdt-selection-bubble-sel.is-link{text-decoration:underline;text-underline-offset:2px;color:#8FD5FF}
.mdt-selection-bubble-sel.is-hl{background:rgba(255,206,84,.30);box-shadow:inset 0 0 0 1px rgba(255,206,84,.42);color:#FFF1CE}
.mdt-selection-bubble-pop{position:absolute;left:50%;top:0;z-index:3;display:flex;align-items:center;gap:2px;padding:4px;border-radius:11px;transform:translate(-50%,-100%);border:1px solid rgba(255,255,255,.12);background:#171B29;box-shadow:0 16px 30px -14px rgba(0,0,0,.95),inset 0 1px 0 rgba(255,255,255,.07);transition:left .22s cubic-bezier(.2,.85,.3,1),top .22s cubic-bezier(.2,.85,.3,1)}
.mdt-selection-bubble-pop::after{content:"";position:absolute;left:var(--mdt-sb-ax,50%);bottom:-4px;width:8px;height:8px;margin-left:-4px;transform:rotate(45deg);background:#171B29;border-right:1px solid rgba(255,255,255,.12);border-bottom:1px solid rgba(255,255,255,.12)}
.mdt-selection-bubble-pop.is-below{transform:translate(-50%,0)}
