js:
var copy = root.querySelector('.mdt-selection-bubble-copy');
var pop = root.querySelector('.mdt-selection-bubble-pop');
var base = root.querySelector('.mdt-selection-bubble-sel');
var marks = Array.prototype.slice.call(root.querySelectorAll('[data-mark]'));
var live = base;

function firstRect(el){
  var rs = el.getClientRects();
  return rs.length ? rs[0] : el.getBoundingClientRect();
}
function place(){
  var host = root.getBoundingClientRect();
  var r = firstRect(live);
  var w = pop.offsetWidth || 210;
  var h = pop.offsetHeight || 34;
  var cx = r.left - host.left + r.width / 2;
  var x = Math.max(w / 2 + 6, Math.min(host.width - w / 2 - 6, cx));
  var topGap = r.top - host.top;
  var below = topGap < h + 12;
  pop.classList.toggle('is-below', below);
  pop.style.left = x.toFixed(1) + 'px';
  pop.style.top = (below ? (r.bottom - host.top + 9) : (topGap - 9)).toFixed(1) + 'px';
  pop.style.setProperty('--mdt-sb-ax', (cx - x + w / 2).toFixed(1) + 'px');
}
function sync(){
  marks.forEach(function(b){
    b.setAttribute('aria-pressed', live.classList.contains(b.getAttribute('data-mark')) ? 'true' : 'false');
  });
}
function dropLive(){
  if (live && live !== base && live.parentNode){
    var p = live.parentNode;
    p.replaceChild(document.createTextNode(live.textContent), live);
    p.normalize();
  }
  live = base;
}
function fromSelection(){
  var sel = window.getSelection ? window.getSelection() : null;
  if (!sel || sel.rangeCount === 0 || sel.isCollapsed) return;
  var r = sel.getRangeAt(0);
  if (!copy.contains(r.commonAncestorContainer) || !String(r).trim()) return;
  dropLive();
  try {
    var span = document.createElement('span');
    span.className = 'mdt-selection-bubble-sel';
    r.surroundContents(span);
    live = span;
    sel.removeAllRanges();
  } catch (err) { live = base; }
  sync();
  place();
}
copy.addEventListener('mouseup', function(){ window.setTimeout(fromSelection, 0); });
copy.addEventListener('keyup', function(){ window.setTimeout(fromSelection, 0); });
marks.forEach(function(b){
  b.addEventListener('click', function(){
    live.classList.toggle(b.getAttribute('data-mark'));
    sync();
    place();
  });
});
var comment = root.querySelector('[data-act="comment"]');
comment.addEventListener('click', function(){
  comment.setAttribute('aria-pressed', comment.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
});
sync();
place();
window.setTimeout(place, 60);

css:
.mdt-editor-rail{
  --mdt-er-ink:#E6EAF4;
  --mdt-er-dim:#78829B;
  --mdt-er-hot:#FFB84D;
  --mdt-er-line:rgba(255,255,255,.08);
  box-sizing:border-box;width:100%;max-width:340px;margin:0 auto;
  border-radius:12px;overflow:hidden;border:1px solid var(--mdt-er-line);background:#0C0E15;
  font:500 12px/1.3 system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  color:var(--mdt-er-ink);-webkit-font-smoothing:antialiased;
}
.mdt-editor-rail *{box-sizing:border-box}
.mdt-editor-rail svg{width:15px;height:15px;display:block;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.mdt-editor-rail-bar{display:flex;flex-wrap:wrap;align-items:center;gap:2px;padding:6px;background:linear-gradient(180deg,#161A24,#11141C);border-bottom:1px solid var(--mdt-er-line)}
.mdt-editor-rail-div{width:1px;height:18px;margin:0 4px;background:var(--mdt-er-line)}
.mdt-editor-rail-seg{display:flex;gap:1px;padding:1px;border-radius:8px;background:rgba(255,255,255,.045)}
.mdt-editor-rail-btn{display:grid;place-items:center;width:28px;height:28px;padding:0;border:0;border-radius:7px;background:transparent;color:var(--mdt-er-dim);cursor:pointer;transition:background .15s ease,color .15s ease,transform .15s ease}
.mdt-editor-rail-btn:hover:not(:disabled){background:rgba(255,255,255,.07);color:var(--mdt-er-ink)}
.mdt-editor-rail-btn:active:not(:disabled){transform:scale(.9)}
.mdt-editor-rail-btn:focus-visible{outline:2px solid var(--mdt-er-hot);outline-offset:1px;color:var(--mdt-er-ink)}
.mdt-editor-rail-btn:disabled{opacity:.32;cursor:not-allowed}
.mdt-editor-rail-btn[aria-pressed="true"]{background:rgba(255,184,77,.16);color:var(--mdt-er-hot);box-shadow:inset 0 0 0 1px rgba(255,184,77,.34)}
.mdt-editor-rail-pick{position:relative;display:block}
.mdt-editor-rail-style{display:flex;align-items:center;gap:4px;height:28px;padding:0 6px 0 9px;border:1px solid var(--mdt-er-line);border-radius:8px;background:rgba(255,255,255,.04);color:var(--mdt-er-ink);font:600 11.5px/1 inherit;font-family:inherit;cursor:pointer;transition:border-color .15s ease,background .15s ease}
.mdt-editor-rail-style:hover{background:rgba(255,255,255,.08);border-color:rgba(255,255,255,.18)}
