.mdt-editor-rail-styletxt{min-width:60px;text-align:left}
.mdt-editor-rail-chev{width:13px;height:13px;color:var(--mdt-er-dim);transition:transform .2s ease}
.mdt-editor-rail-style[aria-expanded="true"] .mdt-editor-rail-chev{transform:rotate(180deg)}
.mdt-editor-rail-list{position:absolute;z-index:4;top:calc(100% + 5px);left:0;display:flex;flex-direction:column;min-width:132px;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,.12);background:#181D28;box-shadow:0 18px 32px -16px rgba(0,0,0,.95)}
.mdt-editor-rail-list[hidden]{display:none}
.mdt-editor-rail-opt{display:block;width:100%;padding:6px 8px;border:0;border-radius:6px;background:transparent;color:#C3CADB;font:500 11.5px/1.2 inherit;font-family:inherit;text-align:left;cursor:pointer;transition:background .13s ease,color .13s ease}
.mdt-editor-rail-opt:hover{background:rgba(255,255,255,.08);color:#fff}
.mdt-editor-rail-opt:focus-visible{outline:2px solid var(--mdt-er-hot);outline-offset:-2px}
.mdt-editor-rail-opt[aria-selected="true"]{color:var(--mdt-er-hot);background:rgba(255,184,77,.12)}
.mdt-editor-rail-doc{padding:14px 14px 16px;background:radial-gradient(120% 80% at 50% 0%,rgba(255,184,77,.05),transparent 60%)}
.mdt-editor-rail-line{margin:0;color:#F1F4FB;transition:font-size .18s ease,padding .18s ease}
.mdt-editor-rail-line.s-p{font-size:13px;font-weight:500;line-height:1.5}
.mdt-editor-rail-line.s-h1{font-size:20px;font-weight:750;letter-spacing:-.02em;line-height:1.2}
