.mdt-editor-rail-line.is-bold{font-weight:800}
.mdt-editor-rail-line.is-italic{font-style:italic}
.mdt-editor-rail-line.is-underline{text-decoration:underline;text-underline-offset:3px;text-decoration-color:rgba(255,184,77,.7)}
.mdt-editor-rail-line.is-mono{font-family:ui-monospace,Menlo,Consolas,monospace;letter-spacing:0}
