@media (prefers-reduced-motion: reduce){
  .mdt-editor-rail-btn{transition:none}
  .mdt-editor-rail-btn:active:not(:disabled){transform:none}
  .mdt-editor-rail-chev{transition:none}
  .mdt-editor-rail-line{transition:none}
  .mdt-editor-rail-style{transition:none}
  .mdt-editor-rail-opt{transition:none}
}

js:
var LABELS = { p:'Paragraph', h1:'Heading 1', h2:'Heading 2', quote:'Quote', code:'Code block' };
var bar = root.querySelector('.mdt-editor-rail-bar');
var styleBtn = root.querySelector('.mdt-editor-rail-style');
var styleTxt = root.querySelector('.mdt-editor-rail-styletxt');
var list = root.querySelector('.mdt-editor-rail-list');
var opts = Array.prototype.slice.call(root.querySelectorAll('.mdt-editor-rail-opt'));
var markBtns = Array.prototype.slice.call(root.querySelectorAll('[data-mark]'));
var alignBtns = Array.prototype.slice.call(root.querySelectorAll('[data-align]'));
var undoBtn = root.querySelector('[data-hist="undo"]');
var redoBtn = root.querySelector('[data-hist="redo"]');
var line = root.querySelector('.mdt-editor-rail-line');
var doc = root.querySelector('.mdt-editor-rail-doc');
var nav = [styleBtn].concat(markBtns, alignBtns, [undoBtn, redoBtn]);

var state = { style:'h2', bold:true, italic:false, underline:false, mono:false, align:'left' };
var past = [], future = [];

function clone(s){ return { style:s.style, bold:s.bold, italic:s.italic, underline:s.underline, mono:s.mono, align:s.align }; }
function render(){
  styleTxt.textContent = LABELS[state.style];
  opts.forEach(function(o){ o.setAttribute('aria-selected', o.getAttribute('data-style') === state.style ? 'true' : 'false'); });
  markBtns.forEach(function(b){ b.setAttribute('aria-pressed', state[b.getAttribute('data-mark')] ? 'true' : 'false'); });
  alignBtns.forEach(function(b){ b.setAttribute('aria-pressed', b.getAttribute('data-align') === state.align ? 'true' : 'false'); });
  var cls = 'mdt-editor-rail-line s-' + state.style;
  ['bold','italic','underline','mono'].forEach(function(k){ if (state[k]) cls += ' is-' + k; });
  line.className = cls;
  doc.style.textAlign = state.align;
  undoBtn.disabled = past.length === 0;
  redoBtn.disabled = future.length === 0;
}
function commit(fn){ past.push(clone(state)); future.length = 0; fn(); render(); }
function openList(open){
  list.hidden = !open;
  styleBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
}
styleBtn.addEventListener('click', function(){ openList(list.hidden); });
opts.forEach(function(o){
  o.addEventListener('click', function(){
    commit(function(){ state.style = o.getAttribute('data-style'); });
    openList(false);
    styleBtn.focus();
  });
});
root.querySelector('.mdt-editor-rail-pick').addEventListener('focusout', function(e){
  if (!e.relatedTarget || !root.querySelector('.mdt-editor-rail-pick').contains(e.relatedTarget)) openList(false);
});
markBtns.forEach(function(b){
  b.addEventListener('click', function(){
    var k = b.getAttribute('data-mark');
    commit(function(){ state[k] = !state[k]; });
  });
});
alignBtns.forEach(function(b){
  b.addEventListener('click', function(){ commit(function(){ state.align = b.getAttribute('data-align'); }); });
});
undoBtn.addEventListener('click', function(){
  if (!past.length) return;
  future.push(clone(state));
  state = past.pop();
  render();
});
redoBtn.addEventListener('click', function(){
  if (!future.length) return;
  past.push(clone(state));
  state = future.pop();
  render();
});
nav.forEach(function(b, i){ b.tabIndex = i === 0 ? 0 : -1; });
bar.addEventListener('keydown', function(e){
  if (e.key === 'Escape'){ openList(false); return; }
  var i = nav.indexOf(e.target);
  if (i < 0) return;
  var d = (e.key === 'ArrowRight') ? 1 : (e.key === 'ArrowLeft') ? -1 : 0;
  if (!d) return;
  e.preventDefault();
  var n = (i + d + nav.length) % nav.length;
  nav.forEach(function(b){ b.tabIndex = -1; });
  nav[n].tabIndex = 0;
  nav[n].focus();
});
render();

css:
.mdt-filter-chips{
  --mdt-fc-ink:#DFE6F2;
  --mdt-fc-dim:#6F7A93;
  --mdt-fc-teal:#4FD8C0;
