js:
var TOTAL = 128;
var XSVG = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 7 10 10M17 7 7 17"/></svg>';
var row = root.querySelector('.mdt-filter-chips-row');
var wrap = root.querySelector('.mdt-filter-chips-addwrap');
var addBtn = root.querySelector('.mdt-filter-chips-add');
var menu = root.querySelector('.mdt-filter-chips-menu');
var items = Array.prototype.slice.call(root.querySelectorAll('.mdt-filter-chips-item'));
var res = root.querySelector('.mdt-filter-chips-res');
var clear = root.querySelector('.mdt-filter-chips-clear');
var q = root.querySelector('.mdt-filter-chips-q');

function chips(){ return Array.prototype.slice.call(root.querySelectorAll('.mdt-filter-chips-chip')); }
function byFacet(f){
  var hit = chips().filter(function(c){ return c.getAttribute('data-facet') === f; });
  return hit[0] || null;
}
function sync(){
  var live = chips().filter(function(c){ return !c.classList.contains('is-off'); });
  var cut = 0;
  live.forEach(function(c){ cut += parseInt(c.getAttribute('data-cut'), 10) || 0; });
  var shown = Math.max(3, TOTAL - cut);
  res.textContent = live.length ? ('Showing ' + shown + ' of ' + TOTAL + ' records') : ('Showing all ' + TOTAL + ' records');
  clear.disabled = live.length === 0;
  chips().forEach(function(c){
    var off = c.classList.contains('is-off');
    c.setAttribute('aria-hidden', off ? 'true' : 'false');
    var x = c.querySelector('.mdt-filter-chips-x');
    if (x) x.tabIndex = off ? -1 : 0;
  });
  items.forEach(function(m){
    var c = byFacet(m.getAttribute('data-target'));
    m.disabled = !!(c && !c.classList.contains('is-off'));
  });
}
function openMenu(open){
  menu.hidden = !open;
  addBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function makeChip(key, val, cut, facet){
  var chip = document.createElement('span');
  chip.className = 'mdt-filter-chips-chip is-off';
  chip.setAttribute('data-facet', facet);
  chip.setAttribute('data-cut', cut);
  var k = document.createElement('span');
  k.className = 'mdt-filter-chips-key';
  k.textContent = key;
  var v = document.createElement('span');
  v.className = 'mdt-filter-chips-val';
  v.textContent = val;
  var x = document.createElement('button');
  x.type = 'button';
  x.className = 'mdt-filter-chips-x';
  x.setAttribute('aria-label', 'Remove ' + key + ' filter');
  x.innerHTML = XSVG;
  chip.appendChild(k);
  chip.appendChild(v);
  chip.appendChild(x);
  row.insertBefore(chip, wrap);
  return chip;
}
row.addEventListener('click', function(e){
  var x = e.target.closest ? e.target.closest('.mdt-filter-chips-x') : null;
  if (!x || !row.contains(x)) return;
  var chip = x.closest('.mdt-filter-chips-chip');
  chip.classList.add('is-off');
  if (chip.getAttribute('data-facet').indexOf('q:') === 0){
    window.setTimeout(function(){ if (chip.parentNode) chip.parentNode.removeChild(chip); sync(); }, 280);
  }
  sync();
});
items.forEach(function(m){
  m.addEventListener('click', function(){
    var c = byFacet(m.getAttribute('data-target'));
    if (c) c.classList.remove('is-off');
    openMenu(false);
    addBtn.focus();
    sync();
  });
});
addBtn.addEventListener('click', function(){ openMenu(menu.hidden); });
wrap.addEventListener('focusout', function(e){
  if (!e.relatedTarget || !wrap.contains(e.relatedTarget)) openMenu(false);
});
wrap.addEventListener('keydown', function(e){ if (e.key === 'Escape'){ openMenu(false); addBtn.focus(); } });
clear.addEventListener('click', function(){
  chips().forEach(function(c){ c.classList.add('is-off'); });
  sync();
});
q.addEventListener('keydown', function(e){
  if (e.key !== 'Enter') return;
  var term = q.value.trim();
  if (!term) return;
  var chip = makeChip('Search', term.slice(0, 18), 22, 'q:' + term);
  q.value = '';
  window.setTimeout(function(){ chip.classList.remove('is-off'); sync(); }, 20);
});
sync();

