js:
var list = root.querySelector('.mdt-bulk-bar-list');
var all = root.querySelector('.mdt-bulk-bar-all');
var meta = root.querySelector('.mdt-bulk-bar-meta');
var num = root.querySelector('.mdt-bulk-bar-num');
var lbl = root.querySelector('.mdt-bulk-bar-lbl');
var tray = root.querySelector('.mdt-bulk-bar-tray');
var acts = Array.prototype.slice.call(root.querySelectorAll('.mdt-bulk-bar-act'));

function rows(){ return Array.prototype.slice.call(root.querySelectorAll('.mdt-bulk-bar-row')); }
function picked(){ return rows().filter(function(r){ return r.querySelector('.mdt-bulk-bar-pick').checked; }); }
function sync(bump){
  var live = rows().filter(function(r){ return !r.classList.contains('is-gone'); });
  var on = picked();
  rows().forEach(function(r){ r.classList.toggle('is-on', r.querySelector('.mdt-bulk-bar-pick').checked); });
  meta.textContent = live.length + (live.length === 1 ? ' item' : ' items');
  root.classList.toggle('is-empty', live.length === 0);
  root.classList.toggle('is-armed', on.length > 0);
  lbl.textContent = on.length === 1 ? 'file selected' : 'files selected';
  if (num.textContent !== String(on.length) || bump){
    num.textContent = String(on.length);
    num.classList.remove('is-bump');
    void num.offsetWidth;
    if (on.length) num.classList.add('is-bump');
  }
  acts.forEach(function(b){ b.tabIndex = on.length ? 0 : -1; });
  tray.setAttribute('aria-hidden', on.length ? 'false' : 'true');
  all.checked = live.length > 0 && on.length === live.length;
  all.indeterminate = on.length > 0 && on.length < live.length;
  all.disabled = live.length === 0;
}
list.addEventListener('change', function(e){
  if (e.target.classList.contains('mdt-bulk-bar-pick')) sync();
});
all.addEventListener('change', function(){
  rows().forEach(function(r){
    if (!r.classList.contains('is-gone')) r.querySelector('.mdt-bulk-bar-pick').checked = all.checked;
  });
  sync();
});
list.addEventListener('transitionend', function(e){
  if (e.propertyName !== 'max-height') return;
  var r = e.target;
  if (r.classList && r.classList.contains('is-gone') && r.parentNode) r.parentNode.removeChild(r);
  sync();
});
acts.forEach(function(b){
  b.addEventListener('click', function(){
    var act = b.getAttribute('data-act');
    var on = picked();
    if (act === 'clear'){
      on.forEach(function(r){ r.querySelector('.mdt-bulk-bar-pick').checked = false; });
    } else if (act === 'tag'){
      var allTagged = on.every(function(r){ return r.classList.contains('is-tagged'); });
      on.forEach(function(r){ r.classList.toggle('is-tagged', !allTagged); });
    } else if (act === 'archive'){
      on.forEach(function(r){
        r.classList.add('is-archived');
        r.querySelector('.mdt-bulk-bar-pick').checked = false;
      });
    } else if (act === 'delete'){
      on.forEach(function(r){
        r.querySelector('.mdt-bulk-bar-pick').checked = false;
        r.classList.add('is-gone');
      });
    }
    sync(true);
  });
});
sync();

