var SORTS = ['Newest', 'Oldest', 'A to Z'];
var seg = root.querySelector('.mdt-view-switch-seg');
var ind = root.querySelector('.mdt-view-switch-ind');
var opts = Array.prototype.slice.call(root.querySelectorAll('.mdt-view-switch-opt'));
var stage = root.querySelector('.mdt-view-switch-stage');
var dense = root.querySelector('.mdt-view-switch-dense');
var sort = root.querySelector('.mdt-view-switch-sort');
var sortTxt = root.querySelector('.mdt-view-switch-sorttxt');
var si = 0;

function current(){
  var hit = opts.filter(function(o){ return o.getAttribute('aria-checked') === 'true'; });
  return hit[0] || opts[0];
}
function place(){
  var o = current();
  ind.style.width = o.offsetWidth + 'px';
  ind.style.transform = 'translateX(' + o.offsetLeft + 'px)';
}
function select(o){
  opts.forEach(function(b){
    var on = b === o;
    b.setAttribute('aria-checked', on ? 'true' : 'false');
    b.tabIndex = on ? 0 : -1;
  });
  stage.className = 'mdt-view-switch-stage v-' + o.getAttribute('data-view') + (stage.classList.contains('is-tight') ? ' is-tight' : '');
  place();
  window.setTimeout(place, 340);
}
opts.forEach(function(o){
  o.tabIndex = o.getAttribute('aria-checked') === 'true' ? 0 : -1;
  o.addEventListener('click', function(){ select(o); });
});
seg.addEventListener('keydown', function(e){
  var i = opts.indexOf(e.target);
  if (i < 0) return;
  var d = (e.key === 'ArrowRight' || e.key === 'ArrowDown') ? 1 : (e.key === 'ArrowLeft' || e.key === 'ArrowUp') ? -1 : 0;
  if (!d) return;
  e.preventDefault();
  var n = opts[(i + d + opts.length) % opts.length];
  select(n);
  n.focus();
});
seg.addEventListener('transitionend', function(e){ if (e.target !== ind) place(); });
dense.addEventListener('click', function(){
  var on = dense.getAttribute('aria-pressed') !== 'true';
  dense.setAttribute('aria-pressed', on ? 'true' : 'false');
  stage.classList.toggle('is-tight', on);
});
sort.addEventListener('click', function(){
  si = (si + 1) % SORTS.length;
  sortTxt.textContent = SORTS[si];
  sort.classList.toggle('is-rev', si === 1);
});
place();
window.setTimeout(place, 80);

