js:
var LADDER = [25, 50, 75, 100, 125, 150, 200, 300, 400];
var range = root.querySelector('.mdt-zoom-stepper-range');
var fill = root.querySelector('.mdt-zoom-stepper-fill');
var pct = root.querySelector('.mdt-zoom-stepper-pct');
var scaler = root.querySelector('.mdt-zoom-stepper-scaler');
var valBtn = root.querySelector('.mdt-zoom-stepper-val');
var menu = root.querySelector('.mdt-zoom-stepper-menu');
var pick = root.querySelector('.mdt-zoom-stepper-pick');
var opts = Array.prototype.slice.call(root.querySelectorAll('.mdt-zoom-stepper-opt'));
var steps = Array.prototype.slice.call(root.querySelectorAll('.mdt-zoom-stepper-step'));
var keys = Array.prototype.slice.call(root.querySelectorAll('.mdt-zoom-stepper-key'));
var MIN = 25, MAX = 400, z = 100;

function setZoom(v){
  z = Math.max(MIN, Math.min(MAX, Math.round(v)));
  range.value = z;
  fill.style.width = ((z - MIN) / (MAX - MIN) * 100).toFixed(2) + '%';
  pct.textContent = z + '%';
  scaler.style.transform = 'scale(' + (z / 100).toFixed(3) + ')';
  steps.forEach(function(b){
    b.disabled = (b.getAttribute('data-step') === '-1') ? z <= MIN : z >= MAX;
  });
  opts.forEach(function(o){ o.setAttribute('aria-selected', parseInt(o.getAttribute('data-z'), 10) === z ? 'true' : 'false'); });
}
function openMenu(open){
  menu.hidden = !open;
  valBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
}
range.addEventListener('input', function(){ setZoom(parseInt(range.value, 10)); });
steps.forEach(function(b){
  b.addEventListener('click', function(){
    var dir = parseInt(b.getAttribute('data-step'), 10);
    var next = z;
    if (dir > 0){
      for (var i = 0; i < LADDER.length; i++){ if (LADDER[i] > z){ next = LADDER[i]; break; } }
      if (next === z) next = MAX;
    } else {
      for (var j = LADDER.length - 1; j >= 0; j--){ if (LADDER[j] < z){ next = LADDER[j]; break; } }
      if (next === z) next = MIN;
    }
    setZoom(next);
  });
});
opts.forEach(function(o){
  o.addEventListener('click', function(){
    setZoom(parseInt(o.getAttribute('data-z'), 10));
    openMenu(false);
    valBtn.focus();
  });
});
keys.forEach(function(k){
  k.addEventListener('click', function(){ setZoom(parseInt(k.getAttribute('data-z'), 10)); });
});
valBtn.addEventListener('click', function(){ openMenu(menu.hidden); });
pick.addEventListener('focusout', function(e){
  if (!e.relatedTarget || !pick.contains(e.relatedTarget)) openMenu(false);
});
pick.addEventListener('keydown', function(e){ if (e.key === 'Escape'){ openMenu(false); valBtn.focus(); } });
setZoom(100);

