.mdt-crumb-bar-menu{position:absolute;z-index:5;top:calc(100% + 6px);left:0;display:flex;flex-direction:column;min-width:140px;padding:4px;border-radius:10px;border:1px solid rgba(255,255,255,.12);background:#1B1A20;box-shadow:0 18px 32px -16px rgba(0,0,0,.95)}
.mdt-crumb-bar-menu[hidden]{display:none}
.mdt-crumb-bar-item{padding:6px 8px;border:0;border-radius:6px;background:transparent;color:#C6BFB2;font:600 11.5px/1.2 inherit;font-family:inherit;text-align:left;cursor:pointer;transition:background .13s ease,color .13s ease}
.mdt-crumb-bar-item:hover{background:rgba(240,177,82,.16);color:#fff}
.mdt-crumb-bar-item:focus-visible{outline:2px solid var(--mdt-cb-gold);outline-offset:-2px}
.mdt-crumb-bar-item.is-cur{color:var(--mdt-cb-gold);background:rgba(240,177,82,.10)}
.mdt-crumb-bar-icon{display:grid;place-items:center;width:24px;height:24px;flex:none;padding:0;border:0;border-radius:7px;background:transparent;color:#8B8579;cursor:pointer;transition:background .15s ease,color .15s ease,transform .15s ease}
.mdt-crumb-bar-icon:hover{background:rgba(255,255,255,.08);color:#fff}
.mdt-crumb-bar-icon:active{transform:scale(.9)}
.mdt-crumb-bar-icon:focus-visible{outline:2px solid var(--mdt-cb-gold);outline-offset:1px}
.mdt-crumb-bar-star[aria-pressed="true"]{color:var(--mdt-cb-gold)}
.mdt-crumb-bar-star[aria-pressed="true"] svg{fill:rgba(240,177,82,.32)}
.mdt-crumb-bar-info[aria-pressed="true"]{color:#E7E3DA;background:rgba(255,255,255,.07)}
.mdt-crumb-bar-meta{display:flex;align-items:center;justify-content:space-between;gap:8px;max-height:0;padding:0 10px;opacity:0;overflow:hidden;transition:max-height .3s ease,opacity .22s ease,padding .3s ease}
.mdt-crumb-bar.is-info .mdt-crumb-bar-meta{max-height:40px;padding:8px 10px;opacity:1}
.mdt-crumb-bar-path{min-width:0;font:500 10px/1.4 ui-monospace,Menlo,Consolas,monospace;letter-spacing:-.01em;color:#8FA8A0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.mdt-crumb-bar-stat{flex:none;font-size:10px;font-weight:500;color:#6E695F;white-space:nowrap}
@media (prefers-reduced-motion: reduce){
  .mdt-crumb-bar-hide{transition:opacity .01s linear}
  .mdt-crumb-bar-meta{transition:none}
  .mdt-crumb-bar-chev{transition:none}
  .mdt-crumb-bar-icon{transition:none}
  .mdt-crumb-bar-icon:active{transform:none}
  .mdt-crumb-bar-dots{transition:none}
}

js:
var dots = root.querySelector('.mdt-crumb-bar-dots');
var hide = root.querySelector('.mdt-crumb-bar-hide');
var cur = root.querySelector('.mdt-crumb-bar-cur');
var curTxt = root.querySelector('.mdt-crumb-bar-curtxt');
var pick = root.querySelector('.mdt-crumb-bar-pick');
var menu = root.querySelector('.mdt-crumb-bar-menu');
var items = Array.prototype.slice.call(root.querySelectorAll('.mdt-crumb-bar-item'));
var star = root.querySelector('.mdt-crumb-bar-star');
var info = root.querySelector('.mdt-crumb-bar-info');
var path = root.querySelector('.mdt-crumb-bar-path');

function slug(s){ return s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); }
function setPath(){
  var trail = ['design-system', 'marketing', 'q3-launch', slug(curTxt.textContent)];
  path.textContent = '~/' + trail.join('/');
}
function openMenu(open){
  menu.hidden = !open;
  cur.setAttribute('aria-expanded', open ? 'true' : 'false');
}
function markItems(){
  items.forEach(function(i){ i.classList.toggle('is-cur', i.textContent === curTxt.textContent); });
}
dots.addEventListener('click', function(){
  hide.classList.add('is-open');
  dots.setAttribute('aria-expanded', 'true');
  var first = hide.querySelector('.mdt-crumb-bar-crumb');
  if (first) first.focus();
});
cur.addEventListener('click', function(){ openMenu(menu.hidden); });
items.forEach(function(i){
  i.addEventListener('click', function(){
    curTxt.textContent = i.textContent;
    markItems();
    setPath();
    openMenu(false);
    cur.focus();
  });
});
pick.addEventListener('focusout', function(e){
  if (!e.relatedTarget || !pick.contains(e.relatedTarget)) openMenu(false);
});
pick.addEventListener('keydown', function(e){ if (e.key === 'Escape'){ openMenu(false); cur.focus(); } });
star.addEventListener('click', function(){
  star.setAttribute('aria-pressed', star.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
});
info.addEventListener('click', function(){
  var on = info.getAttribute('aria-pressed') !== 'true';
  info.setAttribute('aria-pressed', on ? 'true' : 'false');
  root.classList.toggle('is-info', on);
});
markItems();
setPath();
